// Package crypto is the server-side encryption of the objects (docs/02
// S-OBJ-13, docs/05 T-7.5): it seals and unseals the object keys and
// encrypts the object data in a DARE-like package format.
//
// Every encrypted object (or multipart upload) has its own random 256-bit
// object key. The object key is sealed (AES-256-GCM) with a key
// encryption key derived (HKDF-SHA256) from a random salt, the bucket and
// object path and:
//
//   - SSE-S3 and SSE-KMS: a data encryption key generated by the KMS
//     (kms.Service) under its default key or the requested one, bound to
//     the object ARN and the client's encryption context; the KMS-sealed
//     data key is stored with the object;
//   - SSE-C: the key the client sends with every request, never stored:
//     only an HMAC of it verifies the key of the later requests (a wrong
//     key is refused with S3 AccessDenied, as AWS does).
//
// The sealed key, the salt, the KMS key id and the cipher are stored in
// the version metadata (xl.meta, internal keys never returned or copied).
//
// The data of every part (a single-request upload is part 1) is encrypted
// with a key derived from the object key and the part number, in packages
// of 64 KiB of plaintext, each sealed with AES-256-GCM (ChaCha20-Poly1305
// on CPUs without AES instructions) under a nonce derived from its
// sequence number, the last package of a part marked final in its
// authenticated data: reordered, truncated, extended or tampered data
// fails to decrypt. A plaintext range maps to whole packages, so that a
// range read decrypts only the packages it needs (PackageRange). The data
// is encrypted before the erasure coding: shards and bitrot hashes cover
// the ciphertext.
package crypto

import (
	"context"
	"log/slog"

	"github.com/r3n3r0/nexo/internal/domain"
	"github.com/r3n3r0/nexo/internal/service/kms"
)

// Deps are the dependencies of the crypto service. KMS is optional: without
// it (or with kms.NewDisabled) SSE-S3 and SSE-KMS fail with
// domain.ErrKMSNotConfigured, SSE-C works.
type Deps struct {
	KMS    kms.Service
	Logger *slog.Logger
}

// SealInput are the parameters of Seal.
type SealInput struct {
	// Bucket and Object are the path the object key is bound to.
	Bucket string
	Object string
	// Request is the encryption to apply (not the zero request).
	Request domain.SSERequest
}

// UnsealInput are the parameters of Unseal and Reseal.
type UnsealInput struct {
	Bucket string
	Object string
	// Metadata is the metadata of the version (or of the multipart
	// upload): the sealed object key and its parameters.
	Metadata map[string]string
	// CustomerKey is the SSE-C key of the request (required for an SSE-C
	// object, refused for the others).
	CustomerKey domain.SSECustomerKey
}

// ObjectKey is the unsealed key of an encrypted object: it encrypts and
// decrypts the data of its parts and derives the ETags of the SSE-C and
// SSE-KMS objects. It never leaves the process.
type ObjectKey struct {
	key    [32]byte
	cipher Cipher
	info   domain.EncryptionInfo
	meta   map[string]string
}

// Service seals and unseals the object keys. Errors wrap the domain
// sentinels: domain.ErrKMSNotConfigured, domain.ErrKMSKeyNotFound,
// domain.ErrKMSUnavailable, domain.ErrDecryption (damaged metadata), and
// S3 errors for the SSE-C requests (missing key: InvalidRequest, wrong key:
// AccessDenied).
type Service interface {
	// Seal creates the key of a new encrypted object; ObjectKey.Metadata
	// is what the version (or upload) stores.
	Seal(ctx context.Context, in SealInput) (ObjectKey, error)
	// Unseal recovers the key of an encrypted version from its metadata
	// (and the client key of an SSE-C object).
	Unseal(ctx context.Context, in UnsealInput) (ObjectKey, error)
	// Reseal re-seals the KMS data key of an SSE-S3 or SSE-KMS version
	// under the current master key of the KMS (master key rotation) and
	// returns the metadata to store instead; the object key and the data
	// are unchanged. SSE-C versions are re-keyed by a copy instead
	// (domain.ErrInvalidArgument).
	Reseal(ctx context.Context, in UnsealInput) (map[string]string, error)
	// Status reports the state of the KMS behind SSE-S3 and SSE-KMS.
	Status(ctx context.Context) (kms.Status, error)
}
